mapper.select:
SELECT FROM fee_charge charge JOIN fee_item item ON item.fee_item_id = charge.fee_item_id WHERE charge.fee_item_id = #{feeItemId} AND item.deleted_dttm IS NULL AND charge.fee_charge_id IN
#{feeChargeId}
ORDER BY charge.fee_charge_id FOR UPDATE

mapper.insert:
INSERT INTO fee_item (
    name, description, reference_year, reference_term_code,
    amount, due_date, status_code,
    created_by_member_id, updated_by_member_id
) VALUES (
    #{name}, #{description}, #{referenceYear}, #{referenceTermCode},
    #{amount}, #{dueDate}, #{status},
    #{createdByMemberId}, #{updatedByMemberId}
)

INSERT INTO fee_charge (
    fee_item_id, member_id, charged_amount, status_code,
    paid_dttm, processed_by_member_id, process_note
) VALUES

    (
        #{charge.feeItemId}, #{charge.memberId},
        #{charge.chargedAmount}, #{charge.status},
        #{charge.paidDttm}, #{charge.processedByMemberId},
        #{charge.processNote}
    )

mapper.update:
UPDATE fee_charge
SET status_code = #{status},
    paid_dttm = #{paidDttm},
    processed_by_member_id = #{processedByMemberId},
    process_note = #{processNote}
WHERE fee_charge_id = #{feeChargeId}

mapper.insert:
INSERT INTO fee_charge_history (
    fee_charge_id, previous_status_code, new_status_code,
    amount, reason, changed_by_member_id, changed_dttm
) VALUES (
    #{feeChargeId}, #{previousStatus}, #{newStatus},
    #{amount}, #{reason}, #{changedByMemberId}, #{changedDttm}
)
